package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.io.StringWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class HelpFormatter_renderWrappedText_TriageGen1Test {

    @Test
    public void testRenderWrappedText_NoWrap() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(10);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(0);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = "This is a long piece of text that should not be wrapped";
        sb = formatter.renderWrappedText(sb, 10, 0, text);

        assertEquals(text, sb.toString());
    }

    @Test
    public void testRenderWrappedText_WithWrap() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(10);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(0);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = "This is a long piece of text that should be wrapped at the 5th character.";
        sb = formatter.renderWrappedText(sb, 10, 0, text);

        String expected = "This is a long\npiece of text that\nshould be wrapped at\nthe 5th character.";
        assertEquals(expected, sb.toString());
    }

    @Test
    public void testRenderWrappedText_WithPad() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(10);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(1);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = "This is a long piece of text that should be wrapped at the 5th character.";
        sb = formatter.renderWrappedText(sb, 10, 2, text);

        String expected = " This is a long\npiece of text that\nshould be wrapped at\nthe 5th character.";
        assertEquals(expected, sb.toString());
    }

    @Test
    public void testRenderWrappedText_EmptyText() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(10);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(0);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = "";
        sb = formatter.renderWrappedText(sb, 10, 0, text);

        assertEquals("", sb.toString());
    }

    @Test
    public void testRenderWrappedText_NullText() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(10);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(0);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = null;
        sb = formatter.renderWrappedText(sb, 10, 0, text);

        assertTrue(sb.toString().isEmpty());
    }

    @Test
    public void testRenderWrappedText_NegativeWidth() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(-10);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(0);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = "This is a long piece of text that should be wrapped";
        sb = formatter.renderWrappedText(sb, 10, 0, text);

        String expected = "This is a long\npiece of text that\nshould be wrapped";
        assertEquals(expected, sb.toString());
    }

    @Test
    public void testRenderWrappedText_ZeroWidth() {
        HelpFormatter formatter = new HelpFormatter();
        formatter.setWidth(0);
        formatter.setNewLine("\n");
        formatter.setSyntaxPrefix("");
        formatter.setOptPrefix("");
        formatter.setLongOptPrefix("");
        formatter.setArgName("");
        formatter.setLeftPadding(0);
        formatter.setDescPadding(0);

        StringBuffer sb = new StringBuffer();
        String text = "This is a long piece of text that should be wrapped";
        sb = formatter.renderWrappedText(sb, 10, 0, text);

        assertTrue(sb.toString().isEmpty());
    }
}
